            return;
        }

        StringBuilder reqStr = new StringBuilder("Request: ");
        for (int i = 0; i < request.length; i++) {
            reqStr.append(i != request.length - 1 ? String.format("%s, ", request[i]) : request[i]);
        }
        reqStr.append(String.format(" ---> %b\n", result));

