        String expected = "include(tuple('admin', 'user'), role) and include(tuple('active', 'pending'), status)";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithEmptyString() {
        String input = "";
        String expected = "";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithWhitespaceOnly() {
        String input = "   ";
        String expected = "   ";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithInAsPartOfWord() {
        String input = "string contains 'in' somewhere";
        String expected = "string contains 'in' somewhere";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithInAtBeginning() {
        String input = "in ('admin', 'user')";
        String expected = "in ('admin', 'user')";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithInAtEnd() {
        String input = "role in";
        String expected = "role in";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithSpecialCharacters() {
        String input = "role in ('admin@domain', 'user#123')";
        String expected = "include(tuple('admin@domain', 'user#123'), role)";
        String result = Util.convertInSyntax(input);
        assertEquals(expected, result);
    }

    @Test
    public void testConvertInSyntaxWithNestedParentheses() {
        String input = "role in (('admin'), ('user'))";
        String expected = "include(tuple(('admin'), ('user')), role)";
