import org.junit.Test;
import org.junit.Before;
import org.junit.After;
import static org.junit.Assert.*;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;

public class NewConfigTests {

    private static final String TEST_CONFIG_FILE = "test_config.conf";
    private static final String NON_EXISTENT_FILE = "non_existent.conf";
    private static final String EMPTY_STRING = "";
    private static final String VALID_CONFIG_CONTENT = "[default]\nkey = value\n";

    @Before
    public void setUp() throws IOException {
        // Create a temporary config file for testing
        File configFile = new File(TEST_CONFIG_FILE);
        FileWriter writer = new FileWriter(configFile);
        writer.write(VALID_CONFIG_CONTENT);
        writer.close();
    }

    @After
    public void tearDown() {
        // Clean up temporary config file
        File configFile = new File(TEST_CONFIG_FILE);
        if (configFile.exists()) {
            configFile.delete();
        }
    }

    @Test
    public void testNewConfigWithValidConfigFile() {
        Config config = Config.newConfig(TEST_CONFIG_FILE);
        assertNotNull("Config object should not be null", config);
    }

    @Test
    public void testNewConfigCreatesNewInstance() {
        Config config1 = Config.newConfig(TEST_CONFIG_FILE);
        Config config2 = Config.newConfig(TEST_CONFIG_FILE);

        assertNotNull("First config object should not be null", config1);
        assertNotNull("Second config object should not be null", config2);
        assertNotSame("Each call should create a new instance", config1, config2);
    }

